#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# Deploying to the Hostinger VPS (docs/ops/hosting.md, .github/workflows/deploy.yml).
# Staging and production already run Traefik on the VPS; this wizard wires one
# environment to it: the GitHub Environment the deploy workflow reads, the folder
# and .env on the VPS. Run it once per environment:
#   scripts/setup/deploy-vps.sh            # staging
#   TARGET=production scripts/setup/deploy-vps.sh
# Never paste a key or a password in a ticket, a chat or a commit.

TARGET="${TARGET:-staging}"
case "$TARGET" in
  staging)    HOST_DEFAULT="staging.jobbbox.ai" ;;
  production) HOST_DEFAULT="app.jobbbox.ai" ;;
  *) echo "TARGET must be staging or production" >&2; exit 1 ;;
esac
ROOT="/opt/jobbbox/$TARGET"
SLUG="jobbbox-$TARGET"
REPO="fnconsult/jobhub"
TOTAL_STAGES=5

gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

# env_var NAME VALUE sets a variable on the $TARGET GitHub Environment.
env_var() {
  if gh_ready && gh variable set "$1" --env "$TARGET" -R "$REPO" --body "$2" >/dev/null 2>&1; then
    printf '  %s✓ set%s %s variable %s = %s\n' "$GREEN" "$RESET" "$TARGET" "$1" "$2"
  else
    SKIPPED+=("$TARGET variable $1=$2 (gh variable set $1 --env $TARGET)")
    warn "could not set $1 on $TARGET"
  fi
}

# env_secret NAME < value  sets a secret on the $TARGET GitHub Environment from stdin.
env_secret() {
  if gh_ready && gh secret set "$1" --env "$TARGET" -R "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$TARGET/$1")
    printf '  %s✓ set%s %s secret %s\n' "$GREEN" "$RESET" "$TARGET" "$1"
  else
    SKIPPED+=("$TARGET secret $1 (gh secret set $1 --env $TARGET)")
    warn "could not set $1 on $TARGET"
  fi
}

banner "Jobbbox on the Hostinger VPS: $TARGET"

stage "The $TARGET GitHub Environment"
say "The deploy workflow reads where and how to deploy from this Environment."
ask JOBHUB_HOST "Domain for $TARGET [$HOST_DEFAULT]:"
JOBHUB_HOST="${JOBHUB_HOST:-$HOST_DEFAULT}"
if gh_ready; then
  gh api -X PUT "repos/$REPO/environments/$TARGET" >/dev/null && say "Environment $TARGET exists."
fi
env_var JOBHUB_ROOT "$ROOT"
env_var JOBHUB_HOST "$JOBHUB_HOST"
env_var JOBHUB_SLUG "$SLUG"
note "Check the domain's DNS A record points at the VPS (72.61.106.167): dig +short $JOBHUB_HOST"
pause

stage "The SSH key GitHub deploys with"
say "GitHub connects as the deploy user (jobbbox-deploy) with a key of its own."
say "Use the private key whose public half is in ~jobbbox-deploy/.ssh/authorized_keys on the VPS."
note "No such key yet? In a terminal of your own: ssh-keygen -t ed25519 -N '' -C github-jobbbox-deploy -f ~/.ssh/github_jobbbox_deploy"
note "then append ~/.ssh/github_jobbbox_deploy.pub to /home/jobbbox-deploy/.ssh/authorized_keys on the VPS."
ask VPS_KEY_FILE "Path to that private key file:"
VPS_KEY_FILE="${VPS_KEY_FILE/#\~/$HOME}"
if [[ -f "$VPS_KEY_FILE" ]]; then
  env_secret VPS_SSH_KEY < "$VPS_KEY_FILE"
else
  SKIPPED+=("$TARGET secret VPS_SSH_KEY: $VPS_KEY_FILE not found")
  warn "$VPS_KEY_FILE not found"
fi
printf '%s' "vps.fnconsult.co" | env_secret VPS_HOST
printf '%s' "jobbbox-deploy" | env_secret VPS_USER
pause

stage "The $TARGET folder on the VPS"
say "On the VPS, as a user with sudo, run:"
note "  sudo mkdir -p $ROOT && sudo chown jobbbox-deploy:\$(id -gn jobbbox-deploy) $ROOT"
note "  sudo usermod -aG docker jobbbox-deploy      # deploy.sh runs docker compose"
note "  docker network inspect n8n_default >/dev/null && echo traefik-network-ok"
say "The deploy user must be able to reach GitHub over HTTPS (the repo is public, no key needed)."
pause "Press Enter once $ROOT exists and belongs to jobbbox-deploy."

stage "The $TARGET .env on the VPS"
say "Every secret the app needs lives in $ROOT/.env, only on the VPS. Start from .env.example:"
note "  curl -fsSL https://raw.githubusercontent.com/$REPO/main/.env.example > $ROOT/.env && chmod 600 $ROOT/.env"
say "Then, on the VPS, generate the three that must never leave it:"
note "  echo \"POSTGRES_PASSWORD=\$(openssl rand -hex 24)\" >> $ROOT/.env"
note "  echo \"AUTH_SECRET=\$(openssl rand -base64 32)\" >> $ROOT/.env"
note "  echo \"SECRETS_MASTER_KEYS=1:\$(openssl rand -base64 32)\" >> $ROOT/.env"
warn "A key of its own per environment: never reuse staging's in production, nor local ones."
say "Then fill in (nano $ROOT/.env), the deploy sets DATABASE_URL and APP_URL itself:"
step "ADMIN_EMAILS: the Administrators' emails"
step "SMTP_URL and MAIL_FROM: magic links do not arrive without them"
step "AI providers and their keys (or enter keys later in Back office → Clés)"
step "STRIPE_*: test-mode keys and prices on staging; webhook https://$JOBHUB_HOST/api/billing/webhook"
step "EXTENSION_ORIGINS: the extension's chrome-extension:// origin(s)"
note "Leave AI_FAKE and STRIPE_API_URL unset: they are for tests only."
pause "Press Enter once $ROOT/.env is filled in."

stage "First deployment"
say "Everything the workflow checks is now in place. Deploy main to $TARGET:"
if [[ "$TARGET" == production ]]; then
  note "  gh workflow run deploy.yml -R $REPO -f target=production -f confirm=jobbbox.ai"
else
  note "  gh workflow run deploy.yml -R $REPO -f target=staging"
fi
say "Or ask the CI/CD agent to deploy $TARGET. It fails early, naming what is missing."
open_url "https://github.com/$REPO/actions/workflows/deploy.yml"
pause

finish
